-- Registre de tous les travailleurs et de toutes les periodes d'emploi.
-- Ce n'est pas la table des fiches hr_employees.

begin;

create table if not exists public.hr_worker_register (
  id bigint generated always as identity primary key,
  line_no integer not null,
  matricule text not null,
  last_name text not null,
  first_name text,
  birth_date date,
  birth_place text,
  sex text,
  poste text,
  hired_at date not null,
  ended_at date,
  nss text,
  status text not null,
  created_at timestamptz not null default now(),
  constraint hr_worker_register_line_uidx unique (line_no),
  constraint hr_worker_register_period_uidx unique (matricule, hired_at),
  constraint hr_worker_register_status_chk check (status in ('ACTIVE', 'DÉSACTIVE'))
);

comment on table public.hr_worker_register is
  'Registre de tous les travailleurs et de chaque periode d''emploi. Distinct des fiches hr_employees.';

create index if not exists hr_worker_register_nss_idx
  on public.hr_worker_register (nss)
  where nss is not null;

alter table public.hr_worker_register enable row level security;

drop policy if exists hr_worker_register_read on public.hr_worker_register;
create policy hr_worker_register_read on public.hr_worker_register
  for select to authenticated
  using (public.erp_has_perm('employees', 'read', null));

drop policy if exists hr_worker_register_write on public.hr_worker_register;
create policy hr_worker_register_write on public.hr_worker_register
  for all to authenticated
  using (public.erp_has_perm('employees', 'update', null))
  with check (public.erp_has_perm('employees', 'update', null));

grant select, insert, update, delete on public.hr_worker_register to authenticated;
grant usage, select on sequence public.hr_worker_register_id_seq to authenticated;

